from fastapi import FastAPI, HTTPException
from .models import Item, ItemCreate, ItemUpdate

app = FastAPI(title="Inventory API", version="0.1.0")

items: dict[int, Item] = {}
_next_id = 1


@app.get("/health")
def health_check() -> dict[str, str]:
    return {"status": "ok"}


@app.get("/items", response_model=list[Item])
def list_items() -> list[Item]:
    return list(items.values())


@app.get("/items/{item_id}", response_model=Item)
def get_item(item_id: int) -> Item:
    if item_id not in items:
        raise HTTPException(status_code=404, detail="Item not found")
    return items[item_id]


@app.post("/items", response_model=Item, status_code=201)
def create_item(body: ItemCreate) -> Item:
    global _next_id
    item = Item(id=_next_id, **body.model_dump())
    items[_next_id] = item
    _next_id += 1
    return item


@app.patch("/items/{item_id}", response_model=Item)
def update_item(item_id: int, body: ItemUpdate) -> Item:
    if item_id not in items:
        raise HTTPException(status_code=404, detail="Item not found")

    updated_item = items[item_id].model_copy(update=body.model_dump(exclude_unset=True))
    items[item_id] = updated_item
    return updated_item


@app.delete("/items/{item_id}", status_code=204)
def delete_item(item_id: int) -> None:
    if item_id not in items:
        raise HTTPException(status_code=404, detail="Item not found")
    del items[item_id]

